unsafe extern "C" fn region_match_name(
    mut r#match: investigation_region_match_t,
) -> *const ::core::ffi::c_char {
    match r#match {
        investigation_region_match_t::INVESTIGATION_REGION_CENTER => {
            return b"center\0".as_ptr() as *const ::core::ffi::c_char;
        }
        investigation_region_match_t::INVESTIGATION_REGION_INTERSECTS => {
            return b"intersects\0".as_ptr() as *const ::core::ffi::c_char;
        }
        investigation_region_match_t::INVESTIGATION_REGION_MIN_INTERSECTION => {
            return b"minimum_intersection\0".as_ptr() as *const ::core::ffi::c_char;
        }
        investigation_region_match_t::INVESTIGATION_REGION_NONE => {
            return b"none\0".as_ptr() as *const ::core::ffi::c_char;
        }
        _ => {}
    }
    return b"none\0".as_ptr() as *const ::core::ffi::c_char;
}
