unsafe extern "C" fn find_camera_context(
    mut cameras: *const fleet_camera_t,
    mut camera_count: ::core::ffi::c_int,
    mut camera_uuid: *const ::core::ffi::c_char,
) -> *const fleet_camera_t {
    let mut i: ::core::ffi::c_int = 0 as ::core::ffi::c_int;
    while i < camera_count {
        if strcmp(
            &raw const (*cameras.offset(i as isize)).camera_uuid as *const ::core::ffi::c_char,
            camera_uuid,
        ) == 0 as ::core::ffi::c_int
        {
            return cameras.offset(i as isize);
        }
        i += 1;
    }
    return ::core::ptr::null::<fleet_camera_t>();
}
